class Solution:
    def minWastedSpace(self, packages: List[int], boxes: List[List[int]]) -> int:
        import bisect
        packages.sort()
        MOD = 10**9 + 7
        best = inf
        for box in boxes:
            box.sort()
            if box[-1] < packages[-1]:
                continue
            wasted = 0
            for p in packages:
                i = bisect.bisect_left(box, p)
                wasted += box[i] - p
            best = min(best, wasted)
        return best % MOD if best < inf else -1

