class Solution {
public:
    int minWastedSpace(vector<int>& packages, vector<vector<int>>& boxes) {
        sort(packages.begin(), packages.end());
        long long best = LLONG_MAX;
        for (auto& box : boxes) {
            sort(box.begin(), box.end());
            if (box.back() < packages.back()) continue;
            long long wasted = 0;
            for (int p : packages)
                wasted += *lower_bound(box.begin(), box.end(), p) - (long long)p;
            best = min(best, wasted);
        }
        return best == LLONG_MAX ? -1 : (int)(best % 1000000007LL);
    }
};

