class Solution {
    public int minWastedSpace(int[] packages, int[][] boxes) {
        Arrays.sort(packages);
        long best = Long.MAX_VALUE;
        for (int[] box : boxes) {
            Arrays.sort(box);
            if (box[box.length - 1] < packages[packages.length - 1]) continue;
            long wasted = 0;
            for (int p : packages) {
                int lo = 0, hi = box.length - 1;
                while (lo < hi) {
                    int mid = (lo + hi) >>> 1;
                    if (box[mid] < p) lo = mid + 1;
                    else hi = mid;
                }
                wasted += box[lo] - (long) p;
            }
            best = Math.min(best, wasted);
        }
        return best == Long.MAX_VALUE ? -1 : (int) (best % 1000000007L);
    }
}

