class Solution {
    public int minWastedSpace(int[] packages, int[][] boxes) {
        Arrays.sort(packages);
        int n = packages.length;
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + packages[i];
        long best = Long.MAX_VALUE;
        for (int[] box : boxes) {
            Arrays.sort(box);
            if (box[box.length - 1] < packages[n - 1]) continue;
            long wasted = 0;
            int lo = 0;
            for (int b : box) {
                int hi = upperBound(packages, lo, b);
                wasted += (long) b * (hi - lo) - (pre[hi] - pre[lo]);
                lo = hi;
                if (lo == n) break;
            }
            best = Math.min(best, wasted);
        }
        return best == Long.MAX_VALUE ? -1 : (int) (best % 1000000007L);
    }
    private int upperBound(int[] a, int lo, int x) {
        int hi = a.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] <= x) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

