var minWastedSpace = function(packages, boxes) {
    packages.sort((a, b) => a - b);
    const n = packages.length;
    const pre = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + packages[i];
    let best = Infinity;
    for (const box of boxes) {
        box.sort((a, b) => a - b);
        if (box[box.length - 1] < packages[n - 1]) continue;
        let wasted = 0, lo = 0;
        for (const b of box) {
            let l = lo, r = n;
            while (l < r) {
                const mid = (l + r) >> 1;
                if (packages[mid] <= b) l = mid + 1;
                else r = mid;
            }
            wasted += b * (l - lo) - (pre[l] - pre[lo]);
            lo = l;
            if (lo === n) break;
        }
        best = Math.min(best, wasted);
    }
    return best === Infinity ? -1 : best % 1000000007;
};
